<script setup lang="ts">
import {computed,onMounted,onBeforeUnmount,ref,nextTick,watch} from 'vue'
import {useWorkbench} from '../stores/scope'
import {request,post,exportFile} from '../api/client'
import {number,percent,type Product,type Evidence,type QueryEntry} from '../domain/types'
const props=defineProps<{kind:string;overlaps:Product[]}>(),emit=defineEmits<{close:[]}>(),store=useWorkbench()
const sameCoordinates=computed(()=>new Set(props.overlaps.map(p=>p.E+':'+(store.metric==='click'?p.click_rate:p.purchase_rate))).size<=1)
const dialog=ref<HTMLElement>(),message=ref(''),busy=ref(false),evidence=ref<Evidence|null>(null),evidenceFocus=ref('')
const draftA=ref<string[]>(['all']),draftB=ref<string[]>(['all']),find=ref(''),notes=ref<Record<string,string>>({}),removeId=ref('')
const evidenceGroup=ref<'a'|'b'>('a')
const evidenceScope=computed(()=>store.view==='compare'?store.comparison?.[evidenceGroup.value].model.scope_id:store.model?.scope_id)
const registered=ref<{id:string;name:string}[]>([]),ack=ref(false),job=ref<{job_id:string;state:string;progress?:Record<string,unknown>;error_code?:string}|null>(null)
const itemFind=ref(''),itemPage=ref<{items:Product[];eligible:number;cursor:number;next_cursor:number|null}|null>(null)
let lastFocus:HTMLElement|null=null,poll:ReturnType<typeof setTimeout>|undefined,findTimer:ReturnType<typeof setTimeout>|undefined,findToken=0
const candidates=ref<QueryEntry[]>(store.index?.queries.slice(0,100)??[]),names=new Map((store.index?.queries??[]).map(q=>[q.key,q.query||'空查询']))
const title=computed(()=>({source:'数据与口径',evidence:'原行证据',reviews:'复核清单',groups:'编辑 A / B 查询组',other:'其他类目的组成',overlap:sameCoordinates.value?'同坐标商品':'邻近商品',import:'数据导入',products:'范围内的商品'}[props.kind]))
const queries=computed(()=>candidates.value)
watch(find,text=>{clearTimeout(findTimer);const token=++findToken,sid=store.index?.snapshot_id;findTimer=setTimeout(async()=>{if(!sid)return;try{const r=await request<{queries:QueryEntry[]}>('/snapshots/'+sid+'/queries?limit=100&find='+encodeURIComponent(text));if(token===findToken&&sid===store.index?.snapshot_id){candidates.value=r.queries;for(const q of r.queries)names.set(q.key,q.query||'空查询')}}catch(e){message.value=(e as Error).message}},200)})
onMounted(async()=>{lastFocus=document.activeElement as HTMLElement;await nextTick();dialog.value?.querySelector<HTMLButtonElement>('button')?.focus();if(props.kind==='groups'&&store.comparison){draftA.value=store.comparison.a.model.exact_queries.length?[...store.comparison.a.model.exact_queries]:['all'];draftB.value=store.comparison.b.model.exact_queries.length?[...store.comparison.b.model.exact_queries]:['all']}if(props.kind==='evidence')await loadEvidence();if(props.kind==='products')await loadItems();if(props.kind==='reviews')await action(async()=>{await store.loadReviews();for(const r of store.reviews)notes.value[r.id]=r.note});if(props.kind==='import')await action(async()=>registered.value=(await request<{files:{id:string;name:string}[]}>('/registered-files')).files)})
onBeforeUnmount(()=>{clearTimeout(poll);clearTimeout(findTimer);++findToken;lastFocus?.focus()})
async function action(fn:()=>Promise<unknown>,success=''){busy.value=true;message.value='';try{await fn();message.value=success}catch(e){message.value=(e as Error).message}finally{busy.value=false}}
function dialogKeys(event:KeyboardEvent){if(event.key==='Escape'){emit('close');return}if(event.key!=='Tab')return;const controls=[...dialog.value!.querySelectorAll<HTMLElement>('button,a,input,select,textarea,[tabindex="0"]')].filter(x=>!(x as HTMLButtonElement).disabled&&x.getClientRects().length),first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
function groupLabel(keys:string[]){return keys.includes('all')?'全部查询':keys.length+' 个查询'}
function toggleGroup(which:'a'|'b',key:string){const target=which==='a'?draftA:draftB;if(key==='all'){target.value=['all'];return}let keys=target.value.filter(k=>k!=='all');keys=keys.includes(key)?keys.filter(k=>k!==key):[...keys,key];if(keys.length>20){message.value='每组最多 20 个精确查询';return}target.value=keys}
async function applyGroups(){if(!draftA.value.length||!draftB.value.length){message.value='A、B 两组都需要选择查询';return}const label=(keys:string[])=>keys.length===1?(names.get(keys[0])??groupLabel(keys)):groupLabel(keys);await action(()=>store.freezeCompare(draftA.value,draftB.value,false,label(draftA.value),label(draftB.value)));if(!store.error)emit('close');else message.value=store.error}
async function exportData(format:'json'|'csv'='json',target:'scope'|'review'|'evidence'='scope'){const params:Record<string,unknown>={format,target,scope_id:target==='evidence'?evidenceScope.value:store.model?.scope_id};if(target==='evidence'){if((store.view==='products'||store.view==='priority'))params.item_id=store.itemFocus;else params.category_id=store.category?.id}if(target==='scope'&&store.view==='compare'){params.target='compare';params.cohort_a=store.comparison?.a.cohort.cohort_id;params.cohort_b=store.comparison?.b.cohort.cohort_id}await action(()=>exportFile(params,text=>message.value=text),'导出完成，文件已下载')}
async function loadItems(cursor=0){if(!store.model)return;await action(async()=>itemPage.value=await request('/scopes/'+store.model!.scope_id+'/items?limit=25&cursor='+cursor+'&find='+encodeURIComponent(itemFind.value)))}
async function loadEvidence(cursor=0){if(!evidenceScope.value)return;const params=new URLSearchParams({cursor:String(cursor),limit:'25'});if((store.view==='products'||store.view==='priority')&&store.itemFocus){params.set('item_id',store.itemFocus);evidenceFocus.value=store.detailProduct?.title??store.itemFocus}else{if(store.category)params.set('category_id',store.category.id);evidenceFocus.value=store.category?.name??'整个范围'}if(store.view==='compare')evidenceFocus.value=evidenceGroup.value.toUpperCase()+' · '+store.comparison?.[evidenceGroup.value].cohort.name+' / '+evidenceFocus.value;await action(async()=>{evidence.value=await request<Evidence>('/scopes/'+evidenceScope.value+'/evidence?'+params)})}
async function pollJob(){if(!job.value)return;try{job.value=await request('/import-jobs/'+job.value.job_id);if(['queued','running'].includes(job.value!.state))poll=setTimeout(pollJob,500);else if(job.value!.state==='succeeded'){message.value='导入完成，快照已经可以选择';await store.load(store.mode)}}catch(e){message.value=(e as Error).message}}
async function importRegistered(id:string){await action(async()=>{job.value=await post('/import-jobs',{registered_file_ids:[id],adapter_id:'normalized-v1',consent_metadata:{license_discrepancy_acknowledged:ack.value}});await pollJob()})}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;await action(async()=>{const form=new FormData();form.append('file',file);job.value=await request('/import-upload',{method:'POST',body:form});await pollJob()})}
</script>
<template>
<div class="drawer-backdrop" @click.self="emit('close')"><section ref="dialog" class="data-drawer" role="dialog" aria-modal="true" aria-labelledby="drawer-title" tabindex="-1" @keydown="dialogKeys"><div class="drawer-head"><div><p class="eyebrow">GOUXU / {{kind.toUpperCase()}}</p><h2 id="drawer-title">{{title}}</h2></div><button aria-label="关闭侧栏" @click="emit('close')">关闭 ×</button></div><div v-if="message" class="notice" role="status">{{message}}</div>
<template v-if="kind==='source'"><span class="data-badge" :class="{demo:store.index?.data_mode==='synthetic'}">{{store.index?.data_mode==='synthetic'?'合成演示 · 非真实统计':'历史搜索日志'}}</span><h3>来源和版本</h3><p>{{store.index?.source.window||'尚未读取快照'}}</p><dl><dt>快照</dt><dd>{{store.index?.snapshot_id||'—'}}</dd><dt>指标版本</dt><dd>{{store.model?.metric_version||'request-item-pair-v1'}}</dd><dt>当前范围</dt><dd>{{store.view==='compare'?'A / B 冻结查询组':store.queryKey==='all'?'全部查询':store.query}}</dd><dt>数据版本</dt><dd>{{store.index?.source.revision||'自建合成样本'}}</dd><template v-for="(hash,file) in store.index?.source.hashes" :key="file"><dt>{{file}}</dt><dd class="break-all">{{hash}}</dd></template></dl><template v-if="store.view==='compare'&&store.comparison"><h3>冻结的两组范围</h3><dl v-for="(group,key) in {A:store.comparison.a,B:store.comparison.b}" :key="key"><dt>{{key}} · {{group.cohort.name}}</dt><dd>{{group.model.requests}} 条请求，E {{group.model.E}} / C {{group.model.C}} / P {{group.model.P}}<br>split：{{group.model.split_policy.join('、')}}</dd></dl></template><h3>读数怎样得到</h3><p>曝光 E 为各请求去重后的曝光商品配对数。点击 C 为同请求内曝光与点击的交集；购买反馈 P 独立与曝光匹配。两项占比分别为 C/E 和 P/E。</p><div v-if="store.model&&store.view!=='compare'" class="evidence-metrics"><span>E <b>{{number(store.model.E)}}</b></span><span>C <b>{{number(store.model.C)}}</b></span><span>P <b>{{number(store.model.P)}}</b></span></div><p>空分母显示“—”。聚焦和相机不改变分母。曝光外反馈单独报告；购买未记录点击仍保留。</p><dl v-if="store.model&&store.view!=='compare'"><dt>曝光外点击</dt><dd>{{number(store.model.orphanC)}}</dd><dt>曝光外购买反馈</dt><dd>{{number(store.model.orphanP)}}</dd><dt>购买但无匹配点击</dt><dd>{{number(store.model.purchaseWithoutClick)}}</dd><dt>元数据连接覆盖率</dt><dd>{{percent(store.model.coverage.metadata_pairs)}}</dd></dl><h3>使用边界</h3><p>KuaiSearch-Lite 是 2025 年历史窗口中的连续一个月，具体绝对月份未明确；相对时间不恢复为日历日期。群组差异是描述性比较，不代表因果效果。</p><p class="license-note">{{store.index?.source.license_status||'HF MIT 与论文 CC BY 4.0 标注存在差异，仍待核清。'}} 原始数据不随站点公开分发。</p><button v-if="store.model" class="primary-button" :disabled="busy" @click="exportData()">导出完整范围与来源</button></template>
<template v-else-if="kind==='evidence'"><label v-if="store.view==='compare'" class="evidence-group">冻结范围 <select v-model="evidenceGroup" @change="loadEvidence()"><option value="a">A · {{store.comparison?.a.cohort.name}}</option><option value="b">B · {{store.comparison?.b.cohort.name}}</option></select></label><p>当前聚焦：{{evidenceFocus}}。保留源文件行号、SHA256 和相对时间索引，用户标识不进入页面。</p><p>{{evidence?.note}}</p><div class="drawer-actions"><button class="primary-button" :disabled="busy" @click="exportData('json','evidence')">证据 JSON</button><button class="secondary-button" :disabled="busy" @click="exportData('csv','evidence')">证据 CSV</button></div><div v-if="!evidence" role="status">读取证据中…</div><template v-else><div class="evidence-navigation"><span>共 {{number(evidence.total)}} 条请求</span><button :disabled="busy||evidence.cursor===0" @click="loadEvidence(Math.max(0,evidence.cursor-25))">上一页</button><button :disabled="busy||evidence.next_cursor==null" @click="loadEvidence(evidence.next_cursor!)">下一页</button></div><article v-for="r in evidence.records" :key="r.request_id" class="evidence-record"><strong>{{r.query||'空查询'}}</strong><dl><dt>请求</dt><dd>{{r.request_id}}</dd><dt>来源</dt><dd>{{r.source_file||'合成 fixture'}} : {{r.source_line??'—'}}</dd><dt>相对时间 / split</dt><dd>{{r.time_index??'—'}} / {{r.split}}</dd><dt>SHA256</dt><dd class="break-all">{{r.source_sha256}}</dd><dt>曝光列表</dt><dd>{{r.impressed_item_ids.join(', ')||'空'}}</dd><dt>点击列表</dt><dd>{{r.clicked_item_ids.join(', ')||'空'}}</dd><dt>购买反馈列表</dt><dd>{{r.purchased_item_ids.join(', ')||'空'}}</dd></dl></article><p v-if="!evidence.records.length">当前聚焦没有请求证据。</p></template></template>
<template v-else-if="kind==='products'"><p>查找与分页不会改变分析范围。选中商品可定位图形或保留门槛下的精确读数。</p><form class="item-search" @submit.prevent="loadItems()"><input v-model="itemFind" type="search" aria-label="查找商品标题或ID" placeholder="商品标题或 ID" maxlength="200"><button class="primary-button" :disabled="busy">查找</button></form><div v-if="itemPage" class="evidence-navigation"><span>{{number(itemPage.eligible)}} 件匹配商品</span><button :disabled="busy||!itemPage.cursor" @click="loadItems(Math.max(0,itemPage.cursor-25))">上一页</button><button :disabled="busy||itemPage.next_cursor==null" @click="loadItems(itemPage.next_cursor!)">下一页</button></div><button v-for="p in itemPage?.items" :key="p.id" class="overlap-item" @click="action(async()=>{await store.selectItem(p.id);await store.refreshProducts();emit('close')})"><i :style="{background:p.color}"/><span>{{p.title}}<small>{{p.id}} · {{p.categoryName}}</small></span><strong>{{number(p.E)}} 条</strong></button><p v-if="itemPage&&!itemPage.items.length">没有匹配的商品。</p></template>
<template v-else-if="kind==='reviews'"><p>清单保存不可变分析范围。备注和复核状态会随本浏览器会话保留。</p><p v-if="!store.reviews.length">清单为空。可从任一详情面板加入复核。</p><article v-for="r in store.reviews" :key="r.id" class="review-card"><div class="review-title"><button @click="action(async()=>{await store.openReview(r);emit('close')})">{{r.name}} ↗</button><span>{{r.status==='reviewed'?'已复核':'待复核'}} · v{{r.version}}</span></div><small>{{r.target_type}} · {{r.snapshot_id}}</small><label>备注<textarea v-model="notes[r.id]" maxlength="2000" rows="3" :aria-label="r.name+'的复核备注'"/></label><div class="review-actions"><button class="secondary-button" :disabled="busy" @click="action(()=>store.updateReview(r,notes[r.id]??'',r.status==='pending'?'reviewed':'pending'),'已保存备注与状态')">{{r.status==='pending'?'保存并标记已复核':'保存并标记待复核'}}</button><button class="text-button" @click="removeId=r.id">移除</button></div><div v-if="removeId===r.id" class="remove-confirm"><span>移除此条复核？</span><button @click="action(()=>store.removeReview(r),'已移除');removeId=''">确认移除</button><button @click="removeId=''">取消</button></div></article><div v-if="store.reviews.length" class="drawer-actions"><button :disabled="busy" class="primary-button" @click="exportData('json','review')">清单 JSON</button><button :disabled="busy" class="secondary-button" @click="exportData('csv','review')">清单 CSV</button></div></template>
<template v-else-if="kind==='groups'"><p>每组可选 1—20 个查询或全部查询。应用后保存两组范围，后续选择不会静默改组。</p><div class="group-summary"><strong>A · {{groupLabel(draftA)}}</strong><strong>B · {{groupLabel(draftB)}}</strong></div><label class="query-search"><span>⌕</span><input v-model="find" type="search" placeholder="查找查询词" aria-label="查找查询组候选"></label><table class="group-table"><thead><tr><th>精确查询</th><th>A</th><th>B</th></tr></thead><tbody><tr v-for="q in [{key:'all',query:'全部查询',requests:store.index?.counts.requests},...queries]" :key="q.key"><td>{{q.query||'空查询'}}</td><td><input type="checkbox" :checked="draftA.includes(q.key)" :aria-label="'A组 '+q.query" @change="toggleGroup('a',q.key)"></td><td><input type="checkbox" :checked="draftB.includes(q.key)" :aria-label="'B组 '+q.query" @change="toggleGroup('b',q.key)"></td></tr></tbody></table><button class="primary-button" :disabled="busy||store.compareLoading" @click="applyGroups">冻结并应用两组</button></template>
<template v-else-if="kind==='other'"><p>“其他”合并低频原类目，仍计入完整范围分母。</p><table><thead><tr><th>原始类目</th><th>曝光配对数</th></tr></thead><tbody><tr v-for="c in store.model?.other_categories" :key="c.id"><td>{{c.name}}</td><td>{{number(c.E)}}</td></tr></tbody></table></template>
<template v-else-if="kind==='overlap'"><p>{{sameCoordinates?'这些商品具有相同曝光数和反馈占比。':'这些商品在当前画面中靠得较近，编号合并显示。'}}逐件选择可查看详情；每件商品的原始坐标与读数均保留。</p><button v-for="p in overlaps" :key="p.id" class="overlap-item" @click="store.selectItem(p.id);emit('close')"><i :style="{background:p.color}"/><span>{{p.title}}<small>{{p.id}} · {{p.categoryName}}</small></span><strong>{{number(p.E)}} 条 / {{percent(store.metric==='click'?p.click_rate:p.purchase_rate)}}</strong></button></template>
<template v-else-if="kind==='import'"><p>导入已有搜索日志，或重新核验已注册文件。订单数据缺少曝光与点击，不能用于本项目统计。</p><h3>已注册文件</h3><label class="consent"><input v-model="ack" type="checkbox">已阅读数据与口径中保留的许可差异</label><button v-for="f in registered" :key="f.id" class="registered-file" :disabled="busy||(f.id!=='demo'&&!ack)" @click="importRegistered(f.id)"><span>{{f.name}}</span>核验并导入 →</button><h3>授权日志</h3><p>接受 normalized-v1 JSON，最大 50MB。必须明确为 authorized_private，包含请求曝光、点击、购买反馈列表与商品元数据；不接受用户画像和原始用户标识。</p><label class="upload-file">选择 JSON 日志<input type="file" accept="application/json,.json" :disabled="busy" @change="upload"></label><div v-if="job" class="job-status" role="status"><strong>{{({queued:'排队中',running:'处理中',succeeded:'导入成功',failed:'导入失败',cancelled:'已取消'} as Record<string,string>)[job.state]||job.state}}</strong><p>{{job.error_code||JSON.stringify(job.progress??{})}}</p><button v-if="['queued','running'].includes(job.state)" @click="action(async()=>{job=await post('/import-jobs/'+job!.job_id+'/cancel',{});await pollJob()})">取消任务</button></div></template>
</section></div>
</template>


